    private void draw(View v,int w,int h,File file)throws IOException{v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);v.getViewTreeObserver().dispatchOnPreDraw();Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);v.draw(new Canvas(bitmap));if(file!=null)try(FileOutputStream stream=new FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();renders++;}
    private void checkLayout(View view){if(view instanceof android.widget.TextView&&!(view instanceof android.widget.EditText)){android.widget.TextView text=(android.widget.TextView)view;android.text.Layout layout=text.getLayout();if(text.getText().length()>0)check(layout!=null&&text.getHeight()>0,"text has no layout: "+text.getText());if(layout!=null)check(layout.getHeight()<=text.getHeight()-text.getCompoundPaddingTop()-text.getCompoundPaddingBottom()+1,"text line clipped: "+text.getText());}if(!(view instanceof android.view.ViewGroup))return;android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){View child=group.getChildAt(i);if(child.getVisibility()!=View.VISIBLE)continue;if(!(group instanceof android.widget.ScrollView)&&!(group instanceof android.widget.HorizontalScrollView)){check(child.getRight()<=group.getWidth()+1,"child exceeds pane width: "+child.getClass().getSimpleName());check(child.getBottom()<=group.getHeight()+1,"child exceeds pane height: "+child.getClass().getSimpleName());}checkLayout(child);}}
    private View find(View v,String value){if(v instanceof android.widget.TextView&&((android.widget.TextView)v).getText().toString().equals(value))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View found=find(g.getChildAt(i),value);if(found!=null)return found;}}return null;}
    private ClockFace findFace(View v){if(v instanceof ClockFace)return (ClockFace)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){ClockFace found=findFace(g.getChildAt(i));if(found!=null)return found;}}return null;}
    private View findPrefix(View v,String value){if(v instanceof android.widget.TextView&&((android.widget.TextView)v).getText().toString().startsWith(value))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View found=findPrefix(g.getChildAt(i),value);if(found!=null)return found;}}return null;}
    private android.widget.EditText findInput(View v){if(v instanceof android.widget.EditText)return (android.widget.EditText)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){android.widget.EditText found=findInput(g.getChildAt(i));if(found!=null)return found;}}return null;}
