            android.os.SystemClock.sleep(600);screen("runtime-keyboard.png");sync(()->{ClockFace preview=findFace(a.getWindow().getDecorView());android.graphics.Rect visible=new android.graphics.Rect();check(preview.getGlobalVisibleRect(visible)&&visible.height()==preview.getHeight(),"keyboard keeps live preview visible");android.widget.EditText input=a.colorEditorForCheck().hexInput();check(input.getGlobalVisibleRect(visible)&&visible.height()==input.getHeight(),"keyboard keeps entire HEX input visible: "+visible+" / "+input.getHeight()+" focus="+input.hasFocus());});
            sync(()->a.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));android.os.SystemClock.sleep(700);waitForIdleSync();
            sync(()->{android.widget.EditText e=a.colorEditorForCheck().hexInput();check(e.getText().toString().equals("#47A1F2"),"inline HEX draft survives rotation");e.setText("invalid");check(e.getError()!=null,"invalid HEX remains a field error");e.setText("#47A1F2");a.getSystemService(android.view.inputmethod.InputMethodManager.class).hideSoftInputFromWindow(e.getWindowToken(),0);Scene.Page p=a.draft.pages.get(0);Scene persisted=Scene.load(getTargetContext().getSharedPreferences("ui_checks",0));check(persisted.color(persisted.pages.get(0),persisted.pages.get(0).slots[0],"time",false,false)==0xff47a1f2,"valid palette edits save automatically");a.selectForCheck(2,0);try{java.lang.reflect.Method show=MainActivity.class.getDeclaredMethod("show");show.setAccessible(true);show.invoke(a);java.lang.reflect.Method select=MainActivity.class.getDeclaredMethod("selectPageInPlace",int.class,int.class,boolean.class,boolean.class);select.setAccessible(true);select.invoke(a,1,0,false,false);java.lang.reflect.Method menu=MainActivity.class.getDeclaredMethod("showPageMenu");menu.setAccessible(true);menu.invoke(a);java.lang.reflect.Field field=MainActivity.class.getDeclaredField("studioDialog");field.setAccessible(true);android.app.Dialog dialog=(android.app.Dialog)field.get(a);android.widget.ListView options=((android.app.AlertDialog)dialog).getListView();options.performItemClick(null,1,options.getAdapter().getItemId(1));dialog.dismiss();}catch(Exception error){throw new AssertionError(error);}String id=a.draft.home;check(a.draft.home.equals(id),"home selected in page controls");});waitForIdleSync();android.os.SystemClock.sleep(250);
            sync(()->a.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));android.os.SystemClock.sleep(700);waitForIdleSync();
            String first=a.draft.pages.get(0).id,second=a.draft.pages.get(1).id,chosen=a.draft.home;
