    private void screen(String name)throws IOException{Bitmap bitmap=getUiAutomation().takeScreenshot();if(bitmap!=null){File out=new File(getTargetContext().getFilesDir(),"qa-0.3.2");out.mkdirs();try(FileOutputStream stream=new FileOutputStream(new File(out,name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}}
    private void dragPage(MainActivity activity,String from,String to)throws Exception{final int[] start=new int[2],end=new int[2];sync(()->{View root=activity.getWindow().getDecorView();View source=findFace(root.findViewWithTag("page:"+from)),target=findFace(root.findViewWithTag("page:"+to));source.getLocationOnScreen(start);target.getLocationOnScreen(end);start[0]+=source.getWidth()/2;start[1]+=source.getHeight()/2;end[0]+=target.getWidth()/2;end[1]+=target.getHeight()/2;});android.util.Log.i("FoldDrag","display="+activity.getDisplay().getDisplayId()+" coords="+java.util.Arrays.toString(start)+" -> "+java.util.Arrays.toString(end));shell("input -d "+activity.getDisplay().getDisplayId()+" draganddrop "+start[0]+" "+start[1]+" "+end[0]+" "+end[1]+" 900");}

    private void swipe(ClockFace f,int direction){long now=android.os.SystemClock.uptimeMillis();float y=f.getHeight()*.75f,end=f.getHeight()*.25f;if(direction<0){float swap=y;y=end;end=swap;}android.view.MotionEvent down=android.view.MotionEvent.obtain(now,now,0,f.getWidth()/2f,y,0),up=android.view.MotionEvent.obtain(now,now+200,1,f.getWidth()/2f,end,0);f.onTouchEvent(down);f.onTouchEvent(up);down.recycle();up.recycle();}
