    private void restore(android.content.SharedPreferences p,java.util.Map<String,?> values){android.content.SharedPreferences.Editor e=p.edit().clear();for(java.util.Map.Entry<String,?> entry:values.entrySet()){String k=entry.getKey();Object v=entry.getValue();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof java.util.Set)e.putStringSet(k,new java.util.HashSet<>((java.util.Set<String>)v));}e.commit();}
