        a=(ClockActivity)startActivitySync(new Intent(getTargetContext(),ClockActivity.class).putExtra("uiCheck",!outer).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ClockActivity activity=a;waitForIdleSync();android.os.SystemClock.sleep(350);
